const r = $json || {};
const plan = r.jarvisPlan || {};
const rawTasks = Array.isArray(plan.tasks) ? plan.tasks : [];
const errors = [];
if (!r.requestId) errors.push('requestId_required');
if (!r.traceId) errors.push('traceId_required');
if (!r.sessionId) errors.push('sessionId_required');
if (!rawTasks.length) errors.push('jarvisPlan.tasks_required');

const ids = new Set();
const tasks = rawTasks.map((t, index) => {
  const taskId = String(t.taskId ?? t.id ?? ('task-' + index));
  if (ids.has(taskId)) errors.push('duplicate_task_id:' + taskId);
  ids.add(taskId);
  const dependencies = Array.isArray(t.dependencies) ? t.dependencies : (Array.isArray(t.dep) ? t.dep.filter(x => x !== -1).map(String) : []);
  return {
    taskId,
    name: String(t.name ?? t.task ?? ''),
    input: t.input ?? t.args ?? {},
    dependencies,
    capabilityRequirements: Array.isArray(t.capabilityRequirements) ? t.capabilityRequirements : [],
    candidateProviders: Array.isArray(t.candidateProviders) ? t.candidateProviders : [],
    candidateModels: Array.isArray(t.candidateModels) ? t.candidateModels : [],
    executionMode: t.executionMode ?? 'unselected',
    status: 'planned'
  };
});

for (const task of tasks) {
  for (const dep of task.dependencies) {
    if (!ids.has(String(dep))) errors.push('unknown_dependency:' + task.taskId + ':' + String(dep));
  }
}

const normalized = {
  schema: 'jarvis.compatible.task-plan.v1',
  requestId: r.requestId,
  traceId: r.traceId,
  sessionId: r.sessionId,
  jobId: r.jobId || null,
  source: 'microsoft-jarvis-compatible-orchestration',
  stage: 'task-planning',
  tasks,
  resourceDecision: r.resourceDecision || { status: 'not-evaluated' },
  permissionState: r.permissionState || 'not-evaluated',
  approvalState: r.approvalState || 'not-evaluated',
  executionAllowed: false,
  executionReason: 'plan-normalization-only; execution must pass provider, permission, approval, resource, and tool gateways',
  normalizedAt: new Date().toISOString()
};

return { valid: errors.length === 0, errors, plan: normalized };
